+/// Account balances rolled up to the first `depth` levels of each account name, sorted by name.
+///
+/// Shallower accounts keep their full name. Roll-ups with a zero balance are left out. Panics if
+/// `depth` is zero.
+pub fn category_totals(ledger: &Ledger, depth: usize) -> Vec<(String, Amount)> {
+    assert!(depth > 0, "depth must be greater than zero");
+
+    let mut totals: BTreeMap<String, Amount> = BTreeMap::new();
+    for tx in ledger.transactions() {
+        for p in &tx.postings {
+            let category = p.account.split(':').take(depth).collect::<Vec<_>>().join(":");
+            *totals.entry(category).or_default() += p.amount;
+        }
+    }
+
+    totals.into_iter().filter(|(_, amount)| *amount != Amount::default()).collect()
+}
+
 /// One line per posting, `date  description  account  amount`, with the amount column right
 /// aligned to the widest amount, then a line with the total of all postings to `account`.
 pub fn statement(ledger: &Ledger, account: &str) -> String {
@@ -45,3 +63,44 @@ pub fn statement(ledger: &Ledger, account: &str) -> String {
