+mod tests {
+    use super::*;
+    use ledger_core::Transaction;
+
+    #[test]
+    fn category_totals_roll_up_sort_and_omit_zeroes() {
+        let mut ledger = Ledger::new();
+        ledger
+            .record(
+                Transaction::new("2026-04-01", "food")
+                    .post("expenses:food:groceries", Amount::from_cents(1250))
+                    .post("expenses:food:dining", Amount::from_cents(500))
+                    .post("assets:bank", Amount::from_cents(-1750)),
+            )
+            .unwrap();
+        ledger
+            .record(
+                Transaction::new("2026-04-02", "offset")
+                    .post("temporary:one:a", Amount::from_cents(100))
+                    .post("temporary:one:b", Amount::from_cents(-100)),
+            )
+            .unwrap();
+
+        assert_eq!(
+            category_totals(&ledger, 2),
+            vec![
+                ("assets:bank".to_string(), Amount::from_cents(-1750)),
+                ("expenses:food".to_string(), Amount::from_cents(1750)),
+            ]
+        );
+    }
+
+    #[test]
+    #[should_panic(expected = "depth must be greater than zero")]
